(function(E){ const x = E["ai-m2"] = E["ai-m2"] || {units:{}}; x.units["ai-9"] = {"grammar":{"id":"c-ai-9-g","level":"B1","course":"ai-internet","unit":"ai-9","title":"Order of steps: before you, once you have, if","titleTr":"Adım sırası: before you, once you have, if","titleFa":"ترتیب مرحله‌ها: before you، once you have، if","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Before you + verb","Before you send anything, ask me."],["Once you have + past participle","Once you have read the emails, list the questions."],["If X is missing, stop and ask me.","If a date is missing, stop and ask me."]]},"wrong":"Before you will send it, ask me.","right":"Before you send it, ask me.","blank":{"sentence":"___ you send anything, show me the draft.","word":"Before","distractors":["After of","Until to"]},"wrong2":"Once you have read, list the questions.","right2":"Once you have read the emails, list the questions.","blank2":{"sentence":"Once you have ___ the file, list the dates.","word":"read","distractors":["reading","to read"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Before you takes the base verb.","tr":"before you'dan sonra yalın fiil gelir.","fa":"بعد از before you شکل ساده‌ی فعل می‌آید.","ex":"Before you delete it, ask me."},{"en":"Once you have takes the past participle.","tr":"once you have'den sonra üçüncü hâl gelir.","fa":"بعد از once you have شکل سوم فعل می‌آید.","ex":"Once you have finished, report back."}],"test":{"en":"Which comes first? Say it with once you have.","tr":"Hangisi önce? once you have ile söyle.","fa":"کدام اول است؟ با once you have بگو."}},"errorWatch":[{"find":["before you will"],"fix":{"en":"After before you, use the base verb.","tr":"before you'dan sonra yalın fiil gelir.","fa":"بعد از before you شکل ساده‌ی فعل بیاور."}}]},"b2":{"id":"c-ai-9-b2","level":"B2","course":"ai-internet","unit":"ai-9","track":"B2","title":"Handing over responsibly: without + -ing, at each stage","titleTr":"Sorumlu devretmek: without + -ing, at each stage","titleFa":"واگذاری مسئولانه: without + ‎-ing، at each stage","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Do not + verb without + -ing","Do not send without asking me."],["at each stage","Report at each stage."]]},"wrong":"Do not send without ask me.","right":"Do not send without asking me.","blank":{"sentence":"Do not delete anything without ___ me.","word":"asking","distractors":["ask","to ask"]},"wrong2":"Report in each stage.","right2":"Report at each stage.","blank2":{"sentence":"Show me the result ___ each stage.","word":"at","distractors":["in","on"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Without takes -ing here.","tr":"Burada without'tan sonra -ing gelir.","fa":"اینجا بعد از without فعل با ‎-ing می‌آید.","ex":"without checking first"},{"en":"At each stage means after every step.","tr":"at each stage, her adımdan sonra demektir.","fa":"at each stage یعنی بعد از هر مرحله.","ex":"Show me the result at each stage."}],"test":{"en":"Is there a verb after without? Add -ing.","tr":"without'tan sonra fiil mi var? -ing ekle.","fa":"بعد از without فعل آمده؟ ‎-ing اضافه کن."}},"errorWatch":[{"find":["without ask"],"fix":{"en":"After without, use -ing.","tr":"without'tan sonra -ing kullan.","fa":"بعد از without از ‎-ing استفاده کن."}}],"useIn":{"en":"B2: add one rule with without + -ing to your brief.","tr":"B2: Brief'ine without + -ing içeren bir kural ekle.","fa":"B2: به شرح کارت یک قاعده با without + ‎-ing اضافه کن."},"exitItem":{"from":"ai-9","kind":"blank","prompt":"Do not send it without ___ me first.","options":["asking","ask","asked"],"correct":0}},"vocab":{"id":"c-ai-9-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-9","goals":["career"],"title":{"en":"Briefing a job","tr":"İş aktarmak","fa":"شرح دادن کار"},"cards":[{"word":"agent","sentence":"An agent can do several steps itself.","meaning":{"en":"An AI tool that can do several steps.","tr":"Birkaç adımı yapabilen yapay zekâ aracı.","fa":"ابزاری که می‌تواند چند مرحله را انجام بدهد."}},{"word":"step","sentence":"The first step is to read the emails.","meaning":{"en":"One part of a longer job.","tr":"Daha uzun bir işin bir parçası.","fa":"یک بخش از یک کار طولانی‌تر."}},{"word":"stop point","sentence":"Add a stop point before sending.","meaning":{"en":"A place where the tool waits for you.","tr":"Aracın seni beklediği yer.","fa":"جایی که ابزار منتظر تو می‌ماند."}},{"word":"report back","sentence":"Report back when you finish.","meaning":{"en":"To tell someone what you did.","tr":"Ne yaptığını birine bildirmek.","fa":"گزارش دادن کاری که کرده‌ای."}}]},"judge":{"id":"c-ai-9-j","course":"ai-internet","unit":"ai-9","type":"judge","title":{"en":"What does this brief have?","tr":"Bu brief'te neler var?","fa":"این شرح کار چه چیزهایی دارد؟"},"prompt":"Read each brief. Which parts does it have?","parts":["Steps","Stop point","Report"],"instruction":{"en":"Tap every part you can find.","tr":"Bulduğun her parçaya dokun.","fa":"روی هر بخشی که پیدا می‌کنی بزن."},"items":[{"by":"Example brief","answer":"Handle this supplier problem for me.","present":[],"fix":{"en":"No steps, no stop, no report.","tr":"Adım, durma, rapor yok.","fa":"نه مرحله، نه توقف، نه گزارش."}},{"by":"Example brief","answer":"Read the invoices, list the late ones, then email each supplier.","present":["Steps"],"fix":{"en":"It would send emails with no stop. Add one.","tr":"Durmadan e-posta gönderir. Durma noktası ekle.","fa":"بدون توقف ایمیل می‌فرستد. یک نقطه‌ی توقف اضافه کن."}},{"by":"Good model","answer":"Read the invoices and list the late ones. Stop before you email anyone. Show me the list.","present":["Steps","Stop point","Report"],"fix":null},{"by":"Example brief","answer":"Read the invoices. Show me the list at the end.","present":["Steps","Report"],"fix":{"en":"It has no stop point, but it sends nothing. Add one before any next step.","tr":"Durma noktası yok ama bir şey göndermiyor. Sonraki adımdan önce ekle.","fa":"نقطه‌ی توقف ندارد، ولی چیزی نمی‌فرستد. پیش از مرحله‌ی بعد یکی اضافه کن."}},{"by":"Good model","answer":"Read this sales table. List the three best months and show the formula. Stop before you change the file. Then show me two rows to check.","present":["Steps","Stop point","Report"],"fix":null}]},"speaking":{"id":"ai-9","course":"ai-internet","unit":"ai-9","topic":{"en":"Say a brief aloud","tr":"Brief'i yüksek sesle söyle","fa":"شرح کار را بلند بگو"},"warmup":{"en":"What job at work takes several small steps?","tr":"İşinde hangi iş birkaç küçük adımdan oluşur?","fa":"کدام کار در شغلت چند مرحله‌ی کوچک دارد؟"},"questions":[{"en":"Say your brief aloud, as if to a tool: steps, one stop point, and the report you want.","tr":"Brief'ini bir araca söyler gibi yüksek sesle söyle: adımlar, bir durma noktası ve istediğin rapor.","fa":"شرحت را طوری بلند بگو که انگار با ابزار حرف می‌زنی: مرحله‌ها، یک نقطه‌ی توقف و گزارشی که می‌خواهی."},{"en":"Your manager says: \"Let the agent email all the suppliers.\" Say where you would stop it.","tr":"Yöneticin diyor ki: \"Let the agent email all the suppliers.\" Onu nerede durduracağını söyle.","fa":"مدیرت می‌گوید: «Let the agent email all the suppliers.» بگو کجا متوقفش می‌کنی."},{"en":"You asked a tool to total a sales table. Tell your manager how you checked it.","tr":"Bir araçtan satış tablosunu toplamasını istedin. Yöneticine nasıl kontrol ettiğini anlat.","fa":"از ابزاری خواستی جدول فروش را جمع بزند. به مدیرت بگو چطور بررسی‌اش کردی."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"First, read...","meaning":{"en":"Starts the steps.","tr":"Adımları başlatır.","fa":"مرحله‌ها را شروع می‌کند."}},{"phrase":"Stop and ask me if...","meaning":{"en":"Gives a stop point.","tr":"Durma noktası verir.","fa":"نقطه‌ی توقف می‌دهد."}}],"model":"First, read the three emails from this week. Then list the open questions. Once you have the list, draft one reply to the customer. Stop and ask me if a date or a price is missing. Before you send anything, show me the draft. I want to check the names and the numbers myself.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I said where the tool must stop.","tr":"Aracın nerede durması gerektiğini söyledim.","fa":"گفتم ابزار کجا باید بایستد."}]},"writing":{"id":"c-ai-9-w","title":{"en":"Brief a three-step job","tr":"Üç adımlı bir iş aktar","fa":"یک کار سه‌مرحله‌ای را شرح بده"},"course":"ai-internet","unit":"ai-9","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"ai-final-1","prompt":{"en":"Write a brief for this job: compare three supplier offers, list the differences in a table, and draft a question for the cheapest supplier. Nothing must be sent.","tr":"Şu iş için brief yaz: üç tedarikçi teklifini karşılaştır, farkları tabloda listele ve en ucuz tedarikçi için bir soru taslağı yaz. Hiçbir şey gönderilmesin.","fa":"برای این کار شرح بنویس: سه پیشنهاد تأمین‌کننده را مقایسه کن، تفاوت‌ها را در جدول بیاور و برای ارزان‌ترین یک سؤال پیش‌نویس کن. هیچ چیز نباید فرستاده شود."},"model":"Compare the three supplier offers below. Once you have read them, list the differences in a table. Then draft one question for the cheapest supplier. If a price is missing, stop and ask me. Before you finish, show me the table and the draft. Do not send anything.","frame":"___ the ___ below. Once you have ___, ___. Then ___. If ___ is missing, stop and ask me. Before you finish, show me ___. Do not send anything.","words":[{"word":"Once you have"},{"word":"stop and ask me"},{"word":"Before you"}],"minWords":30,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Add one rule with without + -ing, and report at each stage.","tr":"B2 yolu: hazır çerçeve yok. without + -ing içeren bir kural ekle ve her aşamada rapor iste.","fa":"مسیر B2: چارچوب آماده نداری. یک قاعده با without + ‎-ing بیاور و گزارش هر مرحله را بخواه."},"own":{"en":"Now write a brief for a three-step job from your own work.","tr":"Şimdi kendi işinden üç adımlı bir iş için brief yaz.","fa":"حالا برای یک کار سه‌مرحله‌ای از شغل خودت شرح بنویس."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Try it on a small, safe job. Check that it stopped where you asked.","tr":"Küçük ve güvenli bir işte dene. İstediğin yerde durup durmadığını kontrol et.","fa":"روی یک کار کوچک و بی‌خطر امتحانش کن. ببین جایی که خواستی ایستاد یا نه."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Check your brief with the colleague test: could a new colleague do it without asking?","tr":"Brief'ini meslektaş testiyle kontrol et: Yeni bir meslektaş soru sormadan yapabilir mi?","fa":"شرحت را با آزمون همکار بررسی کن: یک همکار جدید می‌تواند بدون سؤال انجامش بدهد؟"},"noTool":true}]},"exit":{"id":"c-ai-9-x","course":"ai-internet","unit":"ai-9","type":"exit","items":[{"from":"ai-9","kind":"mcq","prompt":"What is an agent?","options":["A type of file that an AI tool can read","An AI tool that can do several steps itself","A paid plan for teams that use AI every day"],"correct":1,"why":{"en":"It can act, so it needs clear limits.","tr":"Eylem yapabilir, bu yüzden net sınırlar ister.","fa":"می‌تواند عمل کند، پس به محدودیت روشن نیاز دارد."},"point":1},{"from":"ai-9","kind":"blank","prompt":"Before you ___ the report, show me the list.","options":["sending","send","will send"],"correct":1,"why":{"en":"After before you, use the base verb.","tr":"before you'dan sonra yalın fiil gelir.","fa":"بعد از before you شکل ساده‌ی فعل می‌آید."},"point":4},{"from":"ai-9","kind":"mcq","prompt":"Where should the last stop point usually be?","options":["At the start of the job","Before anything is sent","Just after it is sent"],"correct":1,"why":{"en":"Never let a tool send without you.","tr":"Bir aracın sensiz göndermesine izin verme.","fa":"نگذار ابزار بدون تو چیزی بفرستد."},"point":1},{"from":"ai-8","kind":"mcq","prompt":"Why change only one thing at a time?","options":["So you can see what helped","So the tool costs you less","So the tool works more quickly"],"correct":0,"why":{"en":"Many changes hide the cause.","tr":"Çok değişiklik nedeni gizler.","fa":"تغییرهای زیاد علت را پنهان می‌کنند."}},{"from":"ai-6","kind":"mcq","prompt":"What does this test: could a new colleague do it without asking?","options":["Whether your colleague is good","Whether the tool is free","Whether your prompt is complete"],"correct":2,"why":{"en":"If not, something is missing.","tr":"Yapamıyorsa bir şey eksiktir.","fa":"اگر نه، چیزی کم است."}},{"from":"ai-2","kind":"blank","prompt":"The message ___ \"not supported\".","options":["speaks","says","tells"],"correct":1,"why":{"en":"A message says something.","tr":"Mesaj için says kullanılır.","fa":"برای پیام از says استفاده می‌شود."}},{"from":"ai-9","kind":"mcq","prompt":"A tool gives you a total for your sales table. What is the best check?","options":["Ask it if it is really sure.","Read the answer again for good English.","See the formula and check a few rows."],"correct":2,"why":{"en":"A neat answer is not proof. A few rows show if the formula works.","tr":"Düzgün bir yanıt kanıt değildir. Birkaç satır formülün işe yarayıp yaramadığını gösterir.","fa":"جواب مرتب دلیل درستی نیست. چند ردیف نشان می‌دهد فرمول درست کار می‌کند یا نه."},"point":2}]},"explain":{"id":"c-ai-9-e","course":"ai-internet","unit":"ai-9","type":"explain","level":"B1","title":{"en":"Hand over a longer job","tr":"Daha uzun bir işi devret","fa":"یک کار طولانی‌تر را واگذار کن"},"objective":{"en":"In this lesson you will learn to brief a longer job with a goal, steps, stop points and a report.","tr":"Bu derste daha uzun bir işi hedef, adımlar, durma noktaları ve raporla aktarmayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک کار طولانی‌تر را با هدف، مرحله‌ها، نقطه‌های توقف و گزارش شرح بدهی."},"hook":{"en":"An agent is an AI tool that can do several steps itself. The more it can do, the clearer your stop points must be.","tr":"Agent, birkaç adımı kendi yapabilen yapay zekâ aracıdır. Ne kadar çok şey yapabilirse durma noktaların o kadar net olmalı.","fa":"ایجنت ابزاری است که خودش چند مرحله را انجام می‌دهد. هرچه کارهای بیشتری بتواند بکند، نقطه‌های توقفت باید روشن‌تر باشند."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"20"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"head":{"en":"The four parts of a brief","tr":"Brief'in dört parçası","fa":"چهار بخش شرح کار"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"In a chat, a wrong answer costs little: you read it and fix it. An agent can act: it can send, buy or delete. So a longer job needs a brief that says where to stop.","tr":"Sohbette yanlış bir yanıtın bedeli küçüktür: Okur, düzeltirsin. Agent ise eylem yapabilir: gönderebilir, satın alabilir, silebilir. Bu yüzden uzun bir iş, nerede durulacağını söyleyen bir brief ister.","fa":"در چت، جواب غلط هزینه‌ی کمی دارد: می‌خوانی و درستش می‌کنی. ولی ایجنت می‌تواند عمل کند: بفرستد، بخرد یا پاک کند. پس کار طولانی‌تر به شرحی نیاز دارد که بگوید کجا بایستد."},"steps":[{"en":"Goal: what is the result?","tr":"Hedef: Sonuç ne?","fa":"هدف: نتیجه چیست؟","ex":"A draft reply to three emails."},{"en":"Steps: in what order?","tr":"Adımlar: Hangi sırayla?","fa":"مرحله‌ها: به چه ترتیبی؟","ex":"Read, list the questions, draft."},{"en":"Stop points: where must it wait for you?","tr":"Durma noktaları: Nerede seni beklemeli?","fa":"نقطه‌های توقف: کجا باید منتظر تو بماند؟","ex":"Stop before anything is sent."},{"en":"Report: what should it show you?","tr":"Rapor: Sana ne göstermeli?","fa":"گزارش: چه چیزی را به تو نشان بدهد؟","ex":"Show me the draft and the open questions."}],"phrases":[{"phrase":"Read these three emails. List the open questions. Draft one reply. Stop before anything is sent, and show me the draft.","meaning":{"en":"A brief to copy.","tr":"Kopyalanacak bir brief.","fa":"یک شرح کار برای کپی."},"copy":true}],"tip":{"en":"Start small. Features differ by tool: Copilot has agents, and ChatGPT and Gemini have deep research features.","tr":"Küçük başla. Özellikler araca göre değişir: Copilot'ta agent'lar, ChatGPT ve Gemini'da derin araştırma özellikleri var.","fa":"کوچک شروع کن. امکانات در هر ابزار فرق دارد: ⁨Copilot⁩ ایجنت دارد و ⁨ChatGPT⁩ و ⁨Gemini⁩ امکان تحقیق عمیق دارند."}},{"head":{"en":"A job with numbers","tr":"Sayılarla bir iş","fa":"کاری با عدد"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"AI can sort, total and compare a table quickly. It can also add up wrongly or change a row, and the answer looks just as neat. So ask for something you can check.","tr":"Yapay zekâ bir tabloyu hızla sıralayabilir, toplayabilir, karşılaştırabilir. Yanlış toplayabilir ya da bir satırı değiştirebilir de; yanıt yine aynı derecede düzgün görünür. Bu yüzden kontrol edebileceğin bir şey iste.","fa":"هوش مصنوعی می‌تواند جدول را سریع مرتب کند، جمع بزند و مقایسه کند. همچنین ممکن است غلط جمع بزند یا یک ردیف را تغییر بدهد و جواب باز هم مرتب به نظر برسد. پس چیزی بخواه که بتوانی بررسی‌اش کنی."},"steps":[{"en":"Take out private columns first.","tr":"Önce özel sütunları çıkar.","fa":"اول ستون‌های خصوصی را حذف کن.","ex":"Customer names become Customer 1, Customer 2."},{"en":"Ask for the formula, not only the result.","tr":"Yalnızca sonucu değil, formülü de iste.","fa":"فقط نتیجه را نخواه، فرمول را هم بخواه.","ex":"Show the formula you used."},{"en":"Check two or three rows yourself.","tr":"İki üç satırı kendin kontrol et.","fa":"دو سه ردیف را خودت بررسی کن.","ex":"Row 12: 40 x 80 = 3,200"}],"phrases":[{"phrase":"Here is a table of supplier deliveries, with names removed. Which supplier was late most often? Show the formula you used and two rows I can check by hand. Do not change the data. If a value is missing, stop and ask me.","meaning":{"en":"A prompt to copy. Change the question.","tr":"Kopyalanacak prompt. Soruyu değiştir.","fa":"پرامپت برای کپی. سؤال را تغییر بده."},"copy":true}],"tip":{"en":"Microsoft tells Excel users to review Copilot's results and see if they match what you wanted. The same goes for any tool. Keep a copy of the first file.","tr":"Microsoft, Excel kullanıcılarına Copilot'un sonuçlarını gözden geçirip istedikleriyle uyuşup uyuşmadığına bakmalarını söylüyor. Bu her araç için geçerli. İlk dosyanın bir kopyasını sakla.","fa":"مایکروسافت به کاربران ⁨Excel⁩ می‌گوید نتیجه‌های ⁨Copilot⁩ را مرور کنند و ببینند با چیزی که خواسته‌اند می‌خواند یا نه. این درباره‌ی هر ابزاری درست است. یک نسخه از فایل اول را نگه دار."}},{"head":{"en":"Say it aloud, then check","tr":"Yüksek sesle söyle, sonra kontrol et","fa":"بلند بگو و بعد بررسی کن"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"Use short sentences when you speak to a tool.","tr":"Araçla konuşurken kısa cümleler kullan.","fa":"وقتی با ابزار حرف می‌زنی جمله‌های کوتاه به کار ببر.","ex":"Read the emails. Then list the questions."},{"en":"Read what it wrote down, especially names and numbers.","tr":"Yazdığını oku, özellikle ad ve sayıları.","fa":"چیزی را که نوشته بخوان، مخصوصاً نام‌ها و عددها.","ex":"Order 4471, not 4417."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Order of steps: before you, once you have, if","tr":"Adım sırası: before you, once you have, if","fa":"ترتیب مرحله‌ها: ⁨before you⁩، ⁨once you have⁩، ⁨if⁩"},"steps":[{"en":"Before you takes the base verb.","tr":"before you'dan sonra yalın fiil gelir.","fa":"بعد از ⁨before you⁩ شکل ساده‌ی فعل می‌آید.","ex":"Before you delete it, ask me."},{"en":"Once you have takes the past participle.","tr":"once you have'den sonra üçüncü hâl gelir.","fa":"بعد از ⁨once you have⁩ شکل سوم فعل می‌آید.","ex":"Once you have finished, report back."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Before you + verb","Before you send anything, ask me."],["Once you have + past participle","Once you have read the emails, list the questions."],["If X is missing, stop and ask me.","If a date is missing, stop and ask me."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a request into a brief","tr":"Bir isteği brief'e çevir","fa":"درخواست را به شرح کار تبدیل کن"},"item":"Deal with my emails.\nThe job: read three emails, list the open questions, draft one reply. A date may be missing. Nothing goes out without you.","answer":"Read these three emails. List the open questions. Draft one reply. If a date is missing, stop and ask me. Stop before anything is sent.","walk":[{"en":"Name the result and the steps.","tr":"Sonucu ve adımları söyle.","fa":"نتیجه و مرحله‌ها را بگو."},{"en":"Add what to do if something is missing.","tr":"Eksik bir şey olursa ne yapılacağını ekle.","fa":"اضافه کن اگر چیزی کم بود چه کند."},{"en":"Add the last stop point.","tr":"Son durma noktasını ekle.","fa":"آخرین نقطه‌ی توقف را اضافه کن."}]},"quick":{"prompt":"Which line is a stop point?","options":["Stop before anything is sent.","Write it nicely for the reader.","Use short words in every line."],"correct":0,"why":{"en":"It tells the tool where to wait for you.","tr":"Araca nerede beklemesi gerektiğini söyler.","fa":"به ابزار می‌گوید کجا منتظر تو بماند."}},"remember":{"en":"Never let a tool send, buy or delete without checking with you first.","tr":"Bir aracın sana sormadan göndermesine, satın almasına ya da silmesine asla izin verme.","fa":"هرگز نگذار ابزار بدون پرسیدن از تو چیزی را بفرستد، بخرد یا پاک کند."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Handing over responsibly: without + -ing, at each stage","tr":"Sorumlu devretmek: without + -ing, at each stage","fa":"واگذاری مسئولانه: ⁨without⁩ + ‎⁨-ing⁩، ⁨at each stage⁩"},"steps":[{"en":"Without takes -ing here.","tr":"Burada without'tan sonra -ing gelir.","fa":"اینجا بعد از ⁨without⁩ فعل با ‎⁨-ing⁩ می‌آید.","ex":"without checking first"},{"en":"At each stage means after every step.","tr":"at each stage, her adımdan sonra demektir.","fa":"⁨at each stage⁩ یعنی بعد از هر مرحله.","ex":"Show me the result at each stage."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Do not + verb without + -ing","Do not send without asking me."],["at each stage","Report at each stage."]]},"body":{"en":"B2: add one rule with without + -ing to your brief.","tr":"B2: Brief'ine without + -ing içeren bir kural ekle.","fa":"⁨B2⁩: به شرح کارت یک قاعده با ⁨without⁩ + ‎⁨-ing⁩ اضافه کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
